import{_ as e,c as r,o as t,ai as o}from"./chunks/framework.BrjRfu4a.js";const u=JSON.parse('{"title":"주요 추진 정책 | 2024년 국고채 시장 | 한국 국채","description":"정부는 외국인 국채 투자 확대 등을 위해 세계국채지수(WGBI) 가입을 국정과제로 지정하여 추진하였습니다. WGBI는 26개(우리나라 포함) 주요 선진국 국채들이 편입되어 있는 세계 최대 채권지수로, 런던증권거래소그룹 산하의 FTSE 러셀에서 관리하는 지수입니다. 전세계 지수 추종자금은 약 2.5~3.0조 달러로 추정됩니다.","frontmatter":{"title":"주요 추진 정책 | 2024년 국고채 시장 | 한국 국채","description":"정부는 외국인 국채 투자 확대 등을 위해 세계국채지수(WGBI) 가입을 국정과제로 지정하여 추진하였습니다. WGBI는 26개(우리나라 포함) 주요 선진국 국채들이 편입되어 있는 세계 최대 채권지수로, 런던증권거래소그룹 산하의 FTSE 러셀에서 관리하는 지수입니다. 전세계 지수 추종자금은 약 2.5~3.0조 달러로 추정됩니다.","head":[["meta",{"property":"og:title","content":"주요 추진 정책 | 2024년 국고채 시장 | 한국 국채"}],["meta",{"property":"og:description","content":"정부는 외국인 국채 투자 확대 등을 위해 세계국채지수(WGBI) 가입을 국정과제로 지정하여 추진하였습니다. WGBI는 26개(우리나라 포함) 주요 선진국 국채들이 편입되어 있는 세계 최대 채권지수로, 런던증권거래소그룹 산하의 FTSE 러셀에서 관리하는 지수입니다. 전세계 지수 추종자금은 약 2.5~3.0조 달러로 추정됩니다."}],["meta",{"property":"og:image","content":"/images/RiskQuantHaun.png"}],["meta",{"property":"og:url","content":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/major-policies"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/major-policies"}],["link",{"rel":"alternate","hreflang":"en","href":"https://risk-quant-haun.github.io/korean-treasury-bonds/2024-market/major-policies"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/major-policies"}],["link",{"rel":"canonical","href":"https://risk-quant-haun.github.io/ko/korean-treasury-bonds/2024-market/major-policies"}]],"date":"2025-03-08T00:00:00.000Z"},"headers":[],"relativePath":"ko/korean-treasury-bonds/2024-market/major-policies.md","filePath":"ko/korean-treasury-bonds/2024-market/major-policies.md"}'),n={name:"ko/korean-treasury-bonds/2024-market/major-policies.md"};function i(s,a,l,h,p,d){return t(),r("div",null,a[0]||(a[0]=[o('<h1 id="🏦-주요-추진-정책" tabindex="-1">🏦 주요 추진 정책 <a class="header-anchor" href="#🏦-주요-추진-정책" aria-label="Permalink to &quot;🏦 주요 추진 정책&quot;">​</a></h1><p><strong>2024년 국고채 시장 | 한국 국채 | 2025.03.08</strong></p><h2 id="_1️⃣-세계국채지수-world-government-bond-index-편입-성공" tabindex="-1">1️⃣ 세계국채지수(World Government Bond Index) 편입 성공 <a class="header-anchor" href="#_1️⃣-세계국채지수-world-government-bond-index-편입-성공" aria-label="Permalink to &quot;1️⃣ 세계국채지수(World Government Bond Index) 편입 성공&quot;">​</a></h2><p>정부는 외국인 국채 투자 확대 등을 위해 세계국채지수(WGBI) 가입을 국정과제로 지정하여 추진하였습니다. WGBI는 26개(우리나라 포함) 주요 선진국 국채들이 편입되어 있는 세계 최대 채권지수로, 런던증권거래소그룹 산하의 FTSE 러셀에서 관리하는 지수입니다. 전세계 지수 추종자금은 약 2.5~3.0조 달러로 추정됩니다.</p><p>2022년 9월, 우리나라는 세계국채지수(WGBI) 편입 후보국이라 할 수 있는 관찰대상국(Watch List)에 최초로 등재되었습니다. 외국인 국채 투자소득 비과세 시행, 외국인 투자자등록제 폐지, 국제예탁결제기구 국채통합계좌 개통, 외환시장 구조개선 등 외국인 투자 접근성을 제고하기 위한 다양한 제도개선 노력에 힘입어 2024년 10월 FTSE 러셀은 한국의 WGBI 편입결정을 발표하였습니다.</p><p>한국 국채의 실제 지수편입시점은 2026년 4월부터이며, 한국의 예상편입 비중은 약 2.05%로 전체 편입국가중 9번째로 큰 규모에 해당합니다. 지수 추종자금 유입에 따라 약 500~600억불 규모의 외국인 투자자금이 유입될 것으로 전망됩니다. 아울러, 외국인 투자여건이 대폭 개선됨에 따라 지수 추종자금 외에 액티브 자금 등도 추가유입 될 것으로 예상됩니다.</p><p>이러한 자금 유입에 따라 금리가 안정되면서, 국민, 기업, 정부의 자금 조달비용이 절감될 것으로 예상되며, 외국인 자금유입에 따라 외환시장 안정에도 기여할 것으로 전망됩니다. 아울러, 장기적인 패시브 자금이 대규모 유입됨에 따라 국채 수요기반이 확충되어 향후 안정적인 중장기 재정운용에 기여할 것으로 예상됩니다. 또한, WGBI 편입으로 글로벌 금융시장에서 우리 경제의 위상이 제고됨에 따라 국가경제 신인도 향상 등에도 기여할 것으로 평가됩니다.</p><h2 id="_2️⃣-외국인-국채-투자-비과세" tabindex="-1">2️⃣ 외국인 국채 투자 비과세 <a class="header-anchor" href="#_2️⃣-외국인-국채-투자-비과세" aria-label="Permalink to &quot;2️⃣ 외국인 국채 투자 비과세&quot;">​</a></h2><p>그간 외국인 국채 투자 양도·이자소득 과세가 외국인 투자 활성화에 걸림돌로 작용한다는 지적이 꾸준히 제기되어 왔습니다. 정부는 글로벌 스탠다드에 부합하는 국채 투자환경을 조성하기 위해 2022년 7월 정부 세법개정안에 &#39;외국인 국채 투자 비과세&#39;를 포함하였으며, 해당 개정안은 같은해 12월 국회를 통과하여 2023년 1월 1일부터 시행되었습니다.</p><p>정부는 업계, 투자자와의 긴밀한 소통을 바탕으로 제도의 편의성을 높이기 위한 노력을 지속하고 있습니다. 비거주자·외국법인 등이 국외투자기구를 통해 국채 등에 투자하는 경우, 국외공모투자기구 뿐 아니라 국외사모투자기구의 경우에도 그 국외투자기구를 이자·양도소득의 실질귀속자로 보아 국외투자기구가 비과세 적용을 직접 신청할 수 있도록 하였습니다. 또한, 거주자·내국법인이 국외투자기구를 통하여 지급받는 국채 등에 대한 이자·양도소득의 경우 원천징수를 하지 않고, 해당 거주자·내국법인이 직접 신고납부 하도록 개정하였습니다. (소득세법 제119조의3, 법인세법 제93조의3 개정, &#39;25.1.1. 시행)</p><h2 id="_3️⃣-국제예탁결제기구-국채통합계좌-개설" tabindex="-1">3️⃣ 국제예탁결제기구 국채통합계좌 개설 <a class="header-anchor" href="#_3️⃣-국제예탁결제기구-국채통합계좌-개설" aria-label="Permalink to &quot;3️⃣ 국제예탁결제기구 국채통합계좌 개설&quot;">​</a></h2><p>외국인이 우리나라 국채에 투자하기 위해서는 국내 상임대리인을 선임하고, 국내 보관기관에 직접 계좌를 개설하여야 했습니다. 정부는 이러한 불편을 해소하기 위해 &#39;국제예탁결제기구(ICSD) 국채통합계좌&#39; 개설을 추진하였습니다. 2023년 8월, 한국예탁결제원과 유로클리어·클리어스트림은 국채통합계좌 운영을 위한 계약을 체결하였으며, 시스템 개발과 시장참가자 테스트 등을 거쳐 2024년 6월 27일 서비스를 정식으로 개통하였습니다.</p><p>국채통합계좌를 통해 국채에 투자할 경우, 외국인은 별도의 국내 계좌 증설 없이 기존 ICSD 계좌를 그대로 사용할 수 있게 되어 투자 편의성이 크게 제고됩니다.</p><h2 id="_4️⃣-외국인투자자-등록제-irc-폐지" tabindex="-1">4️⃣ 외국인투자자 등록제(IRC) 폐지 <a class="header-anchor" href="#_4️⃣-외국인투자자-등록제-irc-폐지" aria-label="Permalink to &quot;4️⃣ 외국인투자자 등록제(IRC) 폐지&quot;">​</a></h2><p>외국인 투자자 등록제는 외국인이 국채를 포함한 국내 상장 증권에 투자를 하기 전 금융감독원에 인적사항을 등록하도록 하는 제도로, 외국인의 국내 투자 걸림돌로 지적되어 왔습니다. 이에 정부는 2023년 1월, 「외국인 투자자 자본시장 접근성 제고방안」의 일환으로 외국인 투자자 등록제 폐지를 발표하였으며, 6월 자본시장법 시행령 개정을 거쳐 2023년 12월부터 외국인 투자자 등록제를 폐지하였습니다.</p><p>이에 따라 2023년 12월부터 개인은 여권번호, 법인은 LEI(Legal Entity Identifier)를 식별수단으로 사용할 수 있게 되었습니다. 이를 통해 외국인의 국채 투자 절차가 간소화되면서 우리나라 국채에 대한 외국인 투자 유인이 한층 강화될 것으로 기대됩니다. 또한, 2024년 6월 관련 규정(금융실명거래 업무해설)을 개정하여 외국법인/펀드가 LEI Corroboration 레벨1이 아닌 레벨2~3에 해당하는 경우에도 계좌를 개설할 수 있도록 허용범위를 확대하였습니다.</p><h2 id="_5️⃣-외환시장-선진화" tabindex="-1">5️⃣ 외환시장 선진화 <a class="header-anchor" href="#_5️⃣-외환시장-선진화" aria-label="Permalink to &quot;5️⃣ 외환시장 선진화&quot;">​</a></h2><p>그간 해외투자자들은 해외소재 외국 금융기관이 은행간 외환시장에 직접 참여할 수 없고, 원화 거래시간이 한정되어 있다는 점 등에 대해 불편을 제기해 왔습니다. 정부는 이러한 불편을 해소하고 우리 외환시장 접근성을 제고하기 위해 2023년 2월, 인가받은 해외소재 외국 금융기관의 국내 외환시장 직접 참여 허용, 외환시장 개장시간 연장, 글로벌 수준의 거래·결제 인프라 마련 등을 내용으로 하는 「외환시장 구조 개선방안」을 발표하였습니다.</p><p>2024년 1월부터 외환시장 구조개선 방안을 시범운영하였으며, 2024년 7월부터 본격 시행하였습니다. 이에 따라 외국인 투자자들은 해외 소재 외국금융기관(RFI)를 통해 외환거래가 가능하며, 외환 거래시간도 익일 02시까지 연장되었습니다. 이에 따라, 외국인의 원화거래 불편이 크게 해소되면서 국고채 투자가 활성화될 것으로 기대됩니다.</p><h2 id="_6️⃣-개인투자용-국채-도입" tabindex="-1">6️⃣ 개인투자용 국채 도입 <a class="header-anchor" href="#_6️⃣-개인투자용-국채-도입" aria-label="Permalink to &quot;6️⃣ 개인투자용 국채 도입&quot;">​</a></h2><p>개인투자용 국채란 매입자격을 개인으로 한정하여 발행하는 저축성 국채를 말합니다. 2023년 3월 국채법 개정안이 국회를 통과하고, 같은 해 9월 시행령·시행규칙 개정 등으로 개인투자용 국채 발행을 위한 법적 근거가 마련되었습니다. 그리고 관련 시스템 구축 등을 거쳐 2024년 6월 개인투자용 국채가 최초로 첫 발행되었습니다. 이를 통해 국민의 안정적인 자산 형성을 뒷받침하는 한편, 금융기관에 집중된 국채 수요를 다변화함으로써 향후 안정적인 국채 발행물량 소화에 기여할 것으로 기대됩니다.</p><h2 id="_7️⃣-국채-30년-만기-선물시장-개설" tabindex="-1">7️⃣ 국채 30년 만기 선물시장 개설 <a class="header-anchor" href="#_7️⃣-국채-30년-만기-선물시장-개설" aria-label="Permalink to &quot;7️⃣ 국채 30년 만기 선물시장 개설&quot;">​</a></h2><p>코로나19 이후 국고채 발행량이 크게 증가함에 따라 20년 이상 초장기물 국채의 위험 관리 수요도 증가하였습니다. 이에 따라 2022년 새정부 국정과제로 &#39;30년 국채선물 도입&#39;이 포함되었고, 시장참가자 등의 의견수렴과 검토를 거쳐 2024년 2월 국채 30년만기 선물시장을 개설하였습니다. 3년(1999년), 5년(2003년), 10년(2008년) 국채선물에 이어 16년만에 국채선물을 도입함에 따라, 초장기 국채 투자에 따른 금리변동 위험을 효과적으로 관리할 수 있는 적절한 헤지 수단을 제공함으로써 초장기 국채거래 활성화 등 국채시장의 인프라 개선에 기여할 것으로 기대됩니다.</p>',23)]))}const k=e(n,[["render",i]]);export{u as __pageData,k as default};
